<template>
	<view class="container">
		<block v-if="lists.length>0">
			<view class="goods-items">
				<view class="goods-item" v-for="(item,index) in lists" :key="index"
					@click="toNext(`/pages/index/goods-detail?goods_id=${item.goods_id}`)">
					<image :src="getFullUrl(item.goods_img)" class="goods-img" mode="scaleToFill" />
					<view class="goods-name">{{item.goods_name}}</view>
					<view class="goods-price">
						<view class="price-left">
							<text class="fuhao">¥</text>
							<text class="jiage">{{item.goods_price}}</text>
						</view>
						<image src="@/static/common/join-cart.png" mode="widthFix" class="cart-img" @click.stop="join_cart(item)"></image>
					</view>
				</view>
			</view>
			<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
		</block>
		<view class="empty-container" v-else>
			<u-empty text="暂无相关商品" :icon="emptyIcon" />
		</view>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				form: {
					pageIndex: 1,
					pageSize: 20,
					cate_id: 0,
					sales_sum:0,
				},
			}
		},
		onLoad(e) {
			_this = this;
			if (e.cate_id) {
				_this.form.cate_id = e.cate_id
			}
			if (e.sales_sum) {
				_this.form.sales_sum = e.sales_sum
			}
			_this.get_goods()
		},
		onReachBottom() {
			if(_this.hasMore){
				_this.form.pageIndex++
				_this.get_goods()
			}
		},
		methods: {
			async get_goods() {
				const data = await _this.$post('port/request_index_goods', _this.form)
				if (data.code == 200) {
					_this.lists.push(...data.result.list)
					_this.hasMore = data.result.list.length>=_this.form.pageSize
				} else {
					_this.hasMore = false
				}
			}
		}
	}
</script>

<style lang="scss" scoped>
	@import "static/css/goods.scss";

	.container {
		height: 100%;
		.goods-items{
			padding-top: 20rpx;
		}
	}
</style>